HELP_TOPICS:dict[str,dict[str,object]]={'getting_started':{'title':'Getting started','intro':'The main Open Hardware Control areas in a few minutes.','steps':('Choose the required device or system area on the left.','Use profiles when several settings should be saved together.','Hardware changes are only transmitted by the corresponding Apply/Start action.','Open Log for technical details when something does not respond.'),'page':0},'lcd':{'title':'Change the LCD','intro':'Images, GIFs, clock and hardware data are managed in the NZXT LCD workspace.','steps':('Open Devices → NZXT Kraken → LCD.','Choose static or animated content and import your own image or GIF when needed.','Hardware data can show CPU, GPU and liquid values with animated designs.','Brightness and orientation are located in Display settings.','During GIF playback OHC coordinates short USB handovers automatically.'),'page':3},'cooling':{'title':'Cooling & fan profiles','intro':'Pump and Kraken radiator fans can use fixed duty or temperature control.','steps':('Open Devices → NZXT Kraken → Cooling.','Use Quiet, Balanced, Performance or Safe for a quick starting point.','Software curves can use CPU temperature while liquid temperature remains a safety monitor.','Always watch temperatures and RPM before using very low duty values.'),'page':1},'rgb':{'title':'RGB Studio','intro':'RGB Studio combines NZXT and OpenRGB devices managed by OHC.','steps':('Detect and name devices in the setup section first.','Test LED zones individually and save the detected LED count.','Select devices or groups, then start an OHC design.','If another OpenRGB window owns the hardware, OHC waits for a safe handover.'),'page':2},'profiles':{'title':'Profiles, import & backup','intro':'Profiles save related cooling, LCD, RGB and appearance settings.','steps':('Open System → Profiles.','Create your own profiles for important states and duplicate them before large changes.','Imported LCD profiles show a preview and unsupported elements before activation.','Use Export or Backup before editing complex profiles.'),'page':5},'openlinkhub':{'title':'Corsair & OpenLinkHub','intro':'Corsair devices are integrated through a local OpenLinkHub instance.','steps':('Open Devices → Corsair · OpenLinkHub.','Check service context, API status and detected devices first.','OHC never changes a foreign system service automatically.','When in doubt compare values with the OpenLinkHub device page.'),'page':8},'settings':{'title':'Settings, language & autostart','intro':'Configure appearance, language, display, dependencies and startup behaviour here.','steps':('Open System → Settings.','The interface can switch between German, English, Spanish and French at any time.','At desktop startup OHC can remain fully minimized in the tray.','Undetected devices/modules can be shown for diagnostics.'),'page':4},'troubleshooting':{'title':'Troubleshooting & Log','intro':'For hardware problems the log is the most useful shared diagnostic source.','steps':('Open Diagnostics → Log and reproduce the problem once.','Use Copy all to include the session in a bug report.','For USB problems check device permissions in Settings.','For RGB problems refresh OHC device detection before running other RGB applications in parallel.'),'page':7},'supported_devices':{'title':'Supported devices','intro':'OHC distinguishes fixed device profiles from hardware reported dynamically by local backends.','steps':('NZXT Kraken: Kraken 2023 (1e71:300e), Kraken Elite 2024 RGB (3012) and Kraken Plus (3014) are supported registry entries.','Kraken 2023 Elite (300c) is detected safely only; writes remain disabled because of its known driver status.','The NZXT 2023 RGB Controller (2012) is controlled through liquidctl.','Thermalright Levita Vision 360 ARGB Black: 1600×720 display through TRCC Linux; pump/radiator fans through confirmed hwmon ''channels.','Additional RGB and Corsair devices follow the dynamic lists of the locally installed OpenRGB and OpenLinkHub versions.','Mainboard/case fans require compatible Linux hwmon PWM and individual physical confirmation; GPU fans are never changed.'),'page':6},'wallpaper_engine':{'title':'Wallpaper Engine','intro':'A reopenable assistant covers Steam, Workshop and the locally installed CaptSilver Plasma plugin.','steps':('Install Wallpaper Engine through Steam and initially subscribe to at least five Workshop wallpapers.',"On Fedora, OHC can download the matching official RPM, verify GitHub's SHA256 digest and install through Polkit/DNF after two "'confirmations; OHC never receives the password.','Point Steam Library at the folder containing steamapps; usually ~/.local/share/Steam. Personal videos belong only in a small ''separate folder.',"Select wallpapers or videos in OHC; advanced options remain available in Plasma's original interface.",'The original state is the default. The optional optimisation can be reverted completely.'),'page':9},'desktop':{'title':'Desktop designs','intro':'Experimental desktop designs modify selected KDE appearance parts with backup and rollback.','steps':('Enable the experimental area in Settings.','Review the planned changes before applying them.','OHC creates a backup before modifications and offers restoration.'),'page':10}}
